    <!-- RIGHT COLUMN -->
    <div class="right-col">

      <div class="headline">浙江大学首获国家科技进步奖特等奖</div>
      <div class="subheadline">同时首次以第一完成单位获得国家技术发明奖一等奖</div>

      <div class="article-columns">
        <div class="party-box">
